import {rebuildThroughEditor,assertEquivalentRecipe} from './editor-rebuild.mjs';
import {bootEditor} from './editor-smoke.mjs';
import test from 'node:test';import assert from 'node:assert/strict';import {unlink,readFile} from 'node:fs/promises';
import {WIDTH,createWorld,makeTool,addStat,place,makeRule,makeDecision,step,interact,nextStep,validWorld,setToolStats,defineTag,makeNode,canConnect,normalizeWorld,generateHistory,makeCreatureTool,addUtilityBranch,makeZone,zoneCells,messageField,inZone,nodeUtilityScore,applyZones,createDemoWorld,makeDirector,makeDirectorRule,sendSignal,activeMessage,connectDirectorInput,debugSnapshot,zonePath,targetPath,nextZoneStep,navigationPath,executeAction} from './public/engine.js';import {makeServer} from './server.mjs';
const rule=(changes)=>Object.assign(makeRule(),changes);
function scene(){const w=createWorld(),s=addStat(w,'Custom charge',0,100,20),a=makeTool('Object A','agent'),b=makeTool('Object B','solid');w.tools.push(a,b);setToolStats(w,a,[s.id]);return {w,s,a,b};}
test('new projects are blank and definitions have only monochrome appearance',()=>{const w=createWorld();assert.deepEqual(w.tools,[]);assert.deepEqual(w.stats,[]);assert.deepEqual(w.entities,[]);assert.ok(validWorld(w));for(const preset of ['custom','solid','liquid','agent']){const t=makeTool('Unthemed',preset);assert.equal(t.color,'#333333');assert.equal(t.image,null);assert.deepEqual(t.rules,[]);}});
test('custom stat effects target the interacting object and clamp to user range',()=>{const {w,s,a,b}=scene(),actor=place(w,a.id,2,2),target=place(w,b.id,3,2);b.rules.push(rule({name:'charge transfer',effectStat:s.id,amount:500}));assert.ok(interact(w,actor,target));assert.equal(actor.stats[s.id],100);assert.equal(target.stats[s.id],undefined);b.rules[0].amount=-500;interact(w,actor,target);assert.equal(actor.stats[s.id],0);assert.ok(validWorld(w));});
test('contact -> coating -> ingestion -> threshold -> custom stat effect is a generic chain',()=>{const {w,s,a,b}=scene();b.collision=false;b.quantity=2;b.rules.push(rule({trigger:'contact',effect:'coat',material:'@self',amount:.5,target:'other'}));a.rules.push(rule({trigger:'tick',target:'self',effect:'ingest',material:b.id,amount:.25}),rule({name:'exposure changes custom charge',trigger:'tick',target:'self',condition:'inside',material:b.id,op:'>=',threshold:.5,effect:'stat',effectStat:s.id,amount:-3}));const material=place(w,b.id,4,4),actor=place(w,a.id,4,4);step(w);assert.equal(actor.inside[b.id],.25);assert.equal(actor.stats[s.id],20);step(w);assert.equal(actor.inside[b.id],.5);assert.equal(actor.stats[s.id],17);for(let i=0;i<12;i++)step(w);assert.equal(material.quantity,0);assert.equal(actor.surface[b.id],0);assert.equal(actor.inside[b.id],2);assert.ok(w.events.some(e=>e.text.includes('surface to inside')));assert.ok(validWorld(w));});
test('conditions can read custom stats and filter arbitrary tags',()=>{const {w,s,a,b}=scene();const tag=defineTag(w,'eligible','Can receive this interaction');b.rules.push(rule({otherTag:tag.id,condition:'stat',conditionTarget:'other',stat:s.id,op:'<',threshold:50,effectStat:s.id,amount:5}));const actor=place(w,a.id,1,1),target=place(w,b.id,2,1);interact(w,actor,target);assert.equal(actor.stats[s.id],20);actor.tags.push(tag.id);interact(w,actor,target);assert.equal(actor.stats[s.id],25);actor.stats[s.id]=60;interact(w,actor,target);assert.equal(actor.stats[s.id],60);});
test('custom-stat utility branches seek targets, respect collision, and interact',()=>{const {w,s,a,b}=scene();b.rules.push(rule({effectStat:s.id,amount:10}));a.decisions.push({...makeDecision(s.id),name:'Recharge',action:'seek',targetTool:b.id});const actor=place(w,a.id,1,1);const target=place(w,b.id,4,1);const wall=makeTool('Barrier','solid');w.tools.push(wall);place(w,wall.id,2,1);assert.notDeepEqual(nextStep(w,actor,target),{x:2,y:1});for(let i=0;i<15;i++)step(w);assert.ok(actor.stats[s.id]>20);assert.ok(actor.trace[0].startsWith('Recharge:'));assert.notEqual(actor.x,2);assert.ok(validWorld(w));});
test('collision, independent instance stats, and user artwork survive serialization',()=>{const {w,s,a,b}=scene();a.image='data:image/png;base64,iVBORw0KGgo=';const one=place(w,a.id,1,1),two=place(w,a.id,1,2);one.stats[s.id]=70;assert.equal(two.stats[s.id],20);place(w,b.id,5,5);assert.equal(place(w,b.id,5,5),null);const copy=JSON.parse(JSON.stringify(w));assert.ok(validWorld(copy));assert.equal(copy.tools[0].image,a.image);copy.tools[0].image='data:text/html;base64,AA==';assert.equal(validWorld(copy),false);});
test('validator rejects malformed rule references, graph actions, ranges, and instances',()=>{const {w,s,a}=scene();assert.ok(validWorld(w));a.rules.push(rule({effectStat:'unknown'}));assert.equal(validWorld(w),false);a.rules=[];a.decisions.push({...makeDecision(s.id),action:'javascript'});assert.equal(validWorld(w),false);a.decisions=[];const e=place(w,a.id,0,0);e.x=1000;assert.equal(validWorld(w),false);});
test('HTTP save/load persists definitions, rules, images, and instances across server restarts',async()=>{let server=makeServer();const listen=()=>new Promise(r=>server.listen(0,'127.0.0.1',r)),close=()=>new Promise(r=>server.close(r));await listen();let origin='http://127.0.0.1:'+server.address().port;const {w,s,a,b}=scene();w.id='test-'+crypto.randomUUID();w.name='Canvas — custom';a.kind='creature';const capability=defineTag(w,'custom-capability','A saved purpose linked to a behavior condition');a.tags.push(capability.id);const condition=Object.assign(makeNode('condition'),{condition:'tag',tag:capability.id});a.brain.push(condition);a.edges.push(['root',condition.id]);Object.assign(w,generateHistory('persistence',25,2));a.image='data:image/jpeg;base64,/9j/AA==';b.rules.push(rule({effectStat:s.id}));place(w,a.id,2,2);try{assert.equal((await fetch(origin+'/')).status,200);let res=await fetch(origin+'/api/projects/'+w.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(w)});assert.equal(res.status,200,await res.text());await close();server=makeServer();await listen();origin='http://127.0.0.1:'+server.address().port;const loaded=await (await fetch(origin+'/api/projects/'+w.id)).json();assert.deepEqual(loaded.tools,w.tools);assert.equal(loaded.tools[0].kind,'creature');assert.equal(loaded.tools[0].spawn.enabled,false);assert.deepEqual(loaded.entities,w.entities);assert.deepEqual(loaded.tagDefs,w.tagDefs);assert.deepEqual(loaded.history,w.history);assert.ok(validWorld(loaded));assert.equal(loaded.name,w.name);assert.ok((await (await fetch(origin+'/api/projects')).json()).some(p=>p.id===w.id));res=await fetch(origin+'/api/projects/'+w.id,{method:'PUT',body:'{}'});assert.equal(res.status,400);res=await fetch(origin+'/api/projects/'+w.id,{method:'PUT',headers:{Origin:'https://other.test'},body:JSON.stringify(w)});assert.equal(res.status,403);}finally{await close();await unlink(new URL('./data/'+w.id+'.json',import.meta.url)).catch(()=>{});}});
test('creating stats never attaches them and each tool owns only its chosen subset',()=>{const w=createWorld(),a=makeTool('A'),b=makeTool('B');w.tools.push(a,b);const early=place(w,a.id,0,0),s=addStat(w,'Capacity',0,10,3);assert.deepEqual(early.stats,{});assert.deepEqual(place(w,b.id,1,0).stats,{});setToolStats(w,a,[s.id]);assert.equal(early.stats[s.id],3);assert.equal(place(w,a.id,2,0).stats[s.id],3);assert.deepEqual(w.entities.find(e=>e.toolId===b.id).stats,{});const extra=addStat(w,'Other',0,20,5);assert.equal(early.stats[extra.id],undefined);setToolStats(w,a,[]);assert.equal(early.stats[s.id],undefined);assert.ok(validWorld(w));});
test('stat effects and conditions never invent absent stats on targets',()=>{const {w,s,a,b}=scene(),actor=place(w,a.id,2,2),target=place(w,b.id,3,2);a.rules.push(rule({effectStat:s.id,target:'other',amount:5}));interact(w,actor,target);assert.equal(target.stats[s.id],undefined);assert.deepEqual(b.statIds,[]);b.rules.push(rule({trigger:'tick',condition:'stat',conditionTarget:'self',stat:s.id,op:'==',threshold:0,target:'self',effect:'tag',tag:defineTag(w,'Unexpected','Should never be assigned').id}));step(w);assert.deepEqual(target.tags,[]);assert.ok(validWorld(w));});
test('defined tag purpose persists, Self tag gates behavior, and names have no magic effects',()=>{const {w,s,a}=scene(),tag=defineTag(w,'conductive','Allows a configured charge-transfer rule; no implicit stats.');a.rules.push(rule({trigger:'tick',selfTag:tag.id,target:'self',effectStat:s.id,amount:4}));const e=place(w,a.id,1,1);step(w);assert.equal(e.stats[s.id],20);e.tags.push(tag.id);step(w);assert.equal(e.stats[s.id],24);assert.equal(w.tagDefs[0].description,'Allows a configured charge-transfer rule; no implicit stats.');assert.ok(validWorld(JSON.parse(JSON.stringify(w))));});
test('behavior graph combines utility scoring, sequences, tag conditions, and custom effects',()=>{const {w,s,a}=scene(),tag=defineTag(w,'capability','Enables the chosen action branch');const r=rule({name:'Custom behavior effect',trigger:'behavior',target:'self',effectStat:s.id,amount:5});a.rules.push(r);const root=makeNode('utility','root'),seq=Object.assign(makeNode('sequence'),{label:'Low charge branch',scoreStat:s.id,weight:1}),condition=Object.assign(makeNode('condition'),{condition:'tag',tag:tag.id}),action=Object.assign(makeNode('action'),{action:'rule',ruleId:r.id}),fallback=Object.assign(makeNode('action'),{label:'Fallback',weight:.01});a.brain=[root,seq,condition,action,fallback];a.edges=[['root',seq.id],['root',fallback.id],[seq.id,condition.id],[seq.id,action.id]];a.brainEnabled=true;const e=place(w,a.id,1,1);step(w);assert.equal(e.stats[s.id],20);assert.equal(e.nodeStatus[condition.id],'failure');assert.equal(e.nodeStatus[fallback.id],'success');e.tags.push(tag.id);step(w);assert.equal(e.stats[s.id],25);assert.equal(e.nodeStatus[action.id],'success');assert.ok(e.trace.some(line=>line.includes('Low charge branch:')));assert.ok(validWorld(w));});
test('selector executes fallback after failure, sequences stop, and graph cycles are rejected',()=>{const {w,s,a}=scene();a.brainEnabled=true;const root=makeNode('selector','root'),condition=Object.assign(makeNode('condition'),{stat:s.id,op:'>',threshold:80}),fallback=Object.assign(makeNode('action'),{label:'Fallback'});a.brain=[root,condition,fallback];a.edges=[['root',condition.id],['root',fallback.id]];const e=place(w,a.id,2,2);step(w);assert.equal(e.nodeStatus[condition.id],'failure');assert.equal(e.nodeStatus[fallback.id],'success');root.type='sequence';step(w);assert.equal(e.nodeStatus[fallback.id],undefined);assert.equal(e.nodeStatus.root,'failure');assert.equal(canConnect(a,condition.id,'root'),false);assert.equal(canConnect(a,'root','root'),false);a.edges.push([fallback.id,condition.id]);assert.equal(validWorld(w),false);});
test('v0.2 migration preserves explicit data, creates editable tag definitions, and adds empty graph/history',()=>{const {w,s,a}=scene();a.tags=['custom-label'];const e=place(w,a.id,3,3);e.stats[s.id]=72;delete w.schema;delete w.tagDefs;delete w.history;delete w.factions;delete w.historySettings;for(const t of w.tools){delete t.statIds;delete t.brain;delete t.brainEnabled;delete t.edges;}const migrated=normalizeWorld(w);assert.equal(migrated.entities[0].stats[s.id],72);assert.equal(migrated.tagDefs[0].name,'custom-label');assert.ok(migrated.tools[0].statIds.includes(s.id));assert.equal(migrated.entities[0].tags[0],migrated.tools[0].tags[0]);assert.ok(validWorld(migrated));});
test('seeded history is reproducible, records succession/conflict, and leaves board definitions alone',()=>{const {w}=scene(),before=JSON.stringify(w),a=generateHistory('same',200,3,['One','Two','Three']),b=generateHistory('same',200,3,['One','Two','Three']);assert.deepEqual(a,b);assert.deepEqual(a.factions.map(f=>f.name),['One','Two','Three']);assert.ok(a.history.some(e=>e.type==='succession'));assert.ok(a.history.some(e=>e.type==='conflict'));assert.equal(JSON.stringify(w),before);Object.assign(w,a);assert.ok(validWorld(w));});
test('creature definitions have no implicit stats/tags and automatic spawning defaults off',()=>{const w=createWorld(),c=makeCreatureTool('My creature');w.tools.push(c);assert.equal(c.kind,'creature');assert.deepEqual(c.statIds,[]);assert.deepEqual(c.tags,[]);assert.equal(c.spawn.enabled,false);assert.equal(c.brainEnabled,true);assert.equal(c.brain[0].type,'utility');for(let i=0;i<250;i++)step(w);assert.equal(w.entities.length,0);assert.ok(validWorld(w));});
test('creatures are painted like objects with independent assigned values and tags',()=>{const w=createWorld(),c=makeCreatureTool('C'),object=makeTool('Object'),stat=addStat(w,'Personal value',-10,100,12),tag=defineTag(w,'my-tag','Only assigned where chosen');w.tools.push(c,object);setToolStats(w,c,[stat.id]);c.tags=[tag.id];const a=place(w,c.id,3,3),b=place(w,c.id,4,3),o=place(w,object.id,5,3);a.stats[stat.id]=55;a.tags=[];assert.equal(b.stats[stat.id],12);assert.deepEqual(b.tags,[tag.id]);assert.deepEqual(o.stats,{});assert.equal(w.entities.length,3);assert.ok(validWorld(w));});
test('creature branch builder puts utility and tag gates in the same executable tree',()=>{const w=createWorld(),c=makeCreatureTool('Actor'),a=addStat(w,'Value A',0,100,20),b=addStat(w,'Value B',0,100,0),tag=defineTag(w,'permission','Allows the higher-scoring behavior');w.tools.push(c);setToolStats(w,c,[a.id,b.id]);const ra=rule({name:'Change A',trigger:'behavior',target:'self',effectStat:a.id,amount:5}),rb=rule({name:'Change B',trigger:'behavior',target:'self',effectStat:b.id,amount:1});c.rules.push(ra,rb);const first=addUtilityBranch(w,c,{name:'First candidate',stat:a.id,direction:'low',weight:2,tag:tag.id,action:'rule',ruleId:ra.id}),second=addUtilityBranch(w,c,{name:'Fallback candidate',stat:b.id,direction:'low',weight:1,action:'rule',ruleId:rb.id});const e=place(w,c.id,1,1);step(w);assert.equal(e.stats[a.id],20);assert.equal(e.stats[b.id],1);assert.equal(e.nodeStatus[first.id],'failure');assert.equal(e.nodeStatus[second.id],'success');e.tags.push(tag.id);step(w);assert.equal(e.stats[a.id],25);assert.equal(e.nodeStatus[first.id],'success');assert.equal(e.nodeStatus[second.id],undefined);assert.ok(validWorld(w));const saved=JSON.parse(JSON.stringify(w));assert.equal(saved.tools[0].spawn.enabled,false);assert.deepEqual(saved.tools[0].edges,c.edges);assert.ok(validWorld(saved));});
test('scored branch builder rejects unassigned stats and preserves existing graph branches',()=>{const w=createWorld(),c=makeCreatureTool(),s=addStat(w,'Registry only');w.tools.push(c);assert.throws(()=>addUtilityBranch(w,c,{name:'Invalid',stat:s.id,direction:'low',weight:1,action:'idle'}),/assigned/);assert.equal(c.brain.length,1);setToolStats(w,c,[s.id]);const one=addUtilityBranch(w,c,{name:'One',stat:s.id,direction:'low',weight:1,action:'idle'}),two=addUtilityBranch(w,c,{name:'Two',stat:s.id,direction:'high',weight:2,action:'wander'});assert.ok(c.edges.some(([a,b])=>a==='root'&&b===one.id));assert.ok(c.edges.some(([a,b])=>a==='root'&&b===two.id));assert.ok(validWorld(w));});
test('independent spawning is opt-in, avoids occupied cells, respects caps and can be disabled',()=>{const w=createWorld(),c=makeCreatureTool('Optional spawn'),wall=makeTool('Barrier','solid'),s=addStat(w,'Chosen value',0,10,4);w.tools.push(c,wall);setToolStats(w,c,[s.id]);place(w,wall.id,32,22);Object.assign(c.spawn,{enabled:true,interval:2,limit:3});for(let i=0;i<10;i++)step(w);const spawned=w.entities.filter(e=>e.toolId===c.id);assert.equal(spawned.length,3);assert.equal(new Set(spawned.map(e=>e.x+','+e.y)).size,3);assert.ok(spawned.every(e=>!(e.x===32&&e.y===22)));assert.ok(spawned.every(e=>e.stats[s.id]===4));spawned[0].stats[s.id]=9;assert.equal(spawned[1].stats[s.id],4);c.spawn.enabled=false;for(const e of spawned)w.entities=w.entities.filter(x=>x!==e);for(let i=0;i<10;i++)step(w);assert.equal(w.entities.filter(e=>e.toolId===c.id).length,0);assert.ok(validWorld(w));});
test('older object definitions upgrade without enabling spawning or changing AI',()=>{const {w,a}=scene();const before=JSON.stringify(a.brain);for(const t of w.tools){delete t.kind;delete t.spawn;}const upgraded=normalizeWorld(w);assert.equal(upgraded.tools[0].kind,'object');assert.equal(upgraded.tools[0].spawn.enabled,false);assert.equal(JSON.stringify(upgraded.tools[0].brain),before);assert.ok(validWorld(upgraded));});
test('pursuit introduction uses generic saved tools for patrol, hints, search and fallback',()=>{const w=createDemoWorld(),bot=w.entities.find(e=>e.id===w.tutorial.botId),target=w.entities.find(e=>e.id===w.tutorial.subjectId),phases=new Set(),walls=new Set(w.entities.filter(e=>w.tools.find(t=>t.id===e.toolId).collision).map(e=>e.x+','+e.y));assert.equal(w.zones.length,4);assert.equal(w.tools.filter(t=>t.kind==='creature').length,2);assert.ok(w.tools.every(t=>!t.spawn.enabled));assert.deepEqual(Object.keys(target.stats),[w.tutorial.noiseId]);assert.deepEqual(Object.keys(bot.stats),[w.tutorial.searchId]);for(let i=0;i<300;i++){step(w);phases.add(activeMessage(w,bot)?'investigate':bot.tags.includes(w.tutorial.searchTag)?'search':'patrol');assert.ok(!walls.has(bot.x+','+bot.y));assert.ok(!walls.has(target.x+','+target.y));assert.ok(validWorld(w));}assert.deepEqual([...phases].sort(),['investigate','patrol','search']);assert.ok(w.directors[0].log.length>=3);w.directors[0].enabled=false;for(let i=0;i<30;i++)step(w);const visited=new Set();for(let i=0;i<50;i++){step(w);visited.add(bot.x);assert.equal(activeMessage(w,bot),null);assert.equal(bot.tags.includes(w.tutorial.searchTag),false);}assert.ok(visited.size>2);const restored=normalizeWorld(JSON.parse(JSON.stringify(w)));delete restored.tutorial;assert.ok(validWorld(restored));for(let i=0;i<20;i++){step(w);step(restored);}assert.deepEqual(restored.entities.map(e=>[e.x,e.y,e.stats,e.tags]),w.entities.map(e=>[e.x,e.y,e.stats,e.tags]));});
test('zone effects use selected stats, tag filters and conditions without assigning missing stats',()=>{const {w,s,a,b}=scene(),tag=defineTag(w,'allowed','Permits area effect'),z=Object.assign(makeZone(),{cells:[2*WIDTH+2],creaturesOnly:false,filterTag:tag.id,conditionStat:s.id,op:'<',threshold:50,effect:'stat',stat:s.id,amount:7});w.zones.push(z);const actor=place(w,a.id,2,2),object=place(w,b.id,2,2);applyZones(w);assert.equal(actor.stats[s.id],20);actor.tags=[tag.id];object.tags=[tag.id];applyZones(w);assert.equal(actor.stats[s.id],27);assert.equal(object.stats[s.id],undefined);actor.stats[s.id]=60;applyZones(w);assert.equal(actor.stats[s.id],60);assert.ok(validWorld(w));});
test('entry-only zones fire once per visit and never create collision',()=>{const {w,s,a}=scene(),z=Object.assign(makeZone('Entry'),{cells:[2*WIDTH+2],creaturesOnly:false,trigger:'enter',effect:'stat',stat:s.id,amount:5});w.zones.push(z);const actor=place(w,a.id,1,2);actor.x=2;applyZones(w);applyZones(w);assert.equal(actor.stats[s.id],25);actor.x=1;applyZones(w);actor.x=2;applyZones(w);assert.equal(actor.stats[s.id],30);assert.ok(inZone(w,actor,z.id));assert.ok(validWorld(w));});
test('zone membership can gate tree branches and multiply utility scores',()=>{const {w,s,a}=scene(),z=Object.assign(makeZone(),{cells:[2*WIDTH+2]});w.zones.push(z);const actor=place(w,a.id,2,2),root=makeNode('selector','root'),condition=Object.assign(makeNode('condition'),{condition:'zone',zoneId:z.id,zoneMode:'inside'}),fallback=makeNode('action');a.brain=[root,condition,fallback];a.edges=[['root',condition.id],['root',fallback.id]];a.brainEnabled=true;step(w);assert.equal(actor.nodeStatus[condition.id],'success');const scored={scoreStat:s.id,direction:'low',weight:1,scoreZone:z.id,scoreZoneMode:'inside',zoneMultiplier:3};assert.ok(Math.abs(nodeUtilityScore(w,actor,scored)-2.4)<.00001);actor.x=1;step(w);assert.equal(actor.nodeStatus[condition.id],'failure');assert.equal(actor.nodeStatus[fallback.id],'success');assert.ok(Math.abs(nodeUtilityScore(w,actor,scored)-.8)<.00001);z.enabled=false;scored.scoreZoneMode='outside';assert.ok(Math.abs(nodeUtilityScore(w,actor,scored)-.8)<.00001);assert.ok(validWorld(w));});
test('zone validation rejects invalid cells and references; older saves gain empty zones',()=>{const {w,a}=scene(),z=makeZone();w.zones.push(z);z.cells=[-1];assert.equal(validWorld(w),false);z.cells=[3];a.brain[0].scoreZone='missing';assert.equal(validWorld(w),false);a.brain[0].scoreZone='';delete w.zones;assert.deepEqual(normalizeWorld(w).zones,[]);assert.ok(validWorld(normalizeWorld(w)));});
test('editor automatically opens the pursuit lab, guide runs bot, zone editing and painting preserve objects',()=>{const {editor,get,tick}=bootEditor(),w=editor.world();assert.equal(w.zones.length,4);assert.ok(get('tutorialGuide').innerHTML.includes('Patrol.'));get('tutorialAction').click();assert.equal(editor.running(),true);tick();assert.ok(w.tick>0);editor.goGuide(3);assert.equal(editor.running(),false);assert.equal(get('behaviorView').classList.contains('hidden'),false);const t=w.tools.find(t=>t.id===w.tutorial.toolId),node=t.brain.find(n=>n.action==='moveTarget');editor.editBrainNode(t.id,node.id);assert.equal(get('nodeZone').value,node.zoneId);get('saveBrainNode').click();assert.ok(validWorld(w));editor.goGuide(4);const z=w.zones.find(z=>z.id===w.tutorial.primaryZone),count=z.cells.length,objects=w.entities.length;editor.setMode('zone');const transform=editor.transform(),event={clientX:transform.x+2.5*transform.size,clientY:transform.y+3.5*transform.size,pointerId:1};get('board').onpointerdown(event);get('board').onpointerup();assert.equal(z.cells.length,count+1);assert.equal(w.entities.length,objects);editor.setMode('zoneErase');get('board').onpointerdown(event);get('board').onpointerup();assert.equal(z.cells.length,count);editor.editZone(z.id);get('zoneAmount').value='7';get('saveZone').click();assert.equal(editor.world().zones.find(area=>area.id===z.id).amount,7);assert.ok(validWorld(editor.world()));editor.adopt(createWorld());assert.equal(editor.world().entities.length,0);assert.equal(get('tutorialGuide').classList.contains('hidden'),true);});

function directorScene(){const w=createWorld(),sourceTool=makeTool('Observed subject'),recipient=makeCreatureTool('Receiver'),other=makeCreatureTool('Unassigned'),s=addStat(w,'Observed value',0,100,20);w.tools.push(sourceTool,recipient,other);setToolStats(w,sourceTool,[s.id]);const source=place(w,sourceTool.id,2,2),actor=place(w,recipient.id,7,2),bystander=place(w,other.id,8,2),zone=Object.assign(makeZone('Destination'),{cells:[2*WIDTH+12]});w.zones.push(zone);const local=Object.assign(makeNode('action'),{label:'Local patrol',weight:.25});recipient.brain.push(local);recipient.edges.push(['root',local.id]);const d=makeDirector('Observer');d.enabled=true;d.watchEntity=source.id;d.recipients=[recipient.id];const r=Object.assign(makeDirectorRule(),{name:'Observed movement',trigger:'move',captureStat:s.id,message:'investigate',destination:'fixed',goalZone:zone.id,weight:5,ttl:20,cooldown:1});delete r.fields;d.rules.push(r);w.directors.push(d);return {w,sourceTool,recipient,other,s,source,actor,bystander,zone,d,r,local};}
test('director is optional, recipients patrol normally without messages, and only assigned creatures receive',()=>{const {w,recipient,s,source,actor,bystander,d}=directorScene();connectDirectorInput(w,recipient,'investigate','utility');step(w);assert.equal(actor.action,'Local patrol');assert.equal(activeMessage(w,actor,'investigate'),null);source.x=3;step(w);const message=activeMessage(w,actor,'investigate');assert.ok(message);assert.equal(messageField(message,'value'),20);assert.equal(Object.hasOwn(message,'sourceId'),false);assert.equal(actor.stats[s.id],undefined);assert.ok(actor.action.includes('moving'));assert.deepEqual(bystander.inbox,[]);assert.equal(d.observations[0].x,3);assert.ok(validWorld(w));});
test('messages expire and disabling a director immediately restores local behavior',()=>{const {w,recipient,source,actor,d,r}=directorScene();r.ttl=2;connectDirectorInput(w,recipient,'investigate','utility');step(w);source.x=3;step(w);assert.ok(activeMessage(w,actor));step(w);step(w);assert.equal(activeMessage(w,actor),null);assert.equal(actor.action,'Local patrol');source.x=4;step(w);assert.ok(activeMessage(w,actor));d.enabled=false;assert.equal(activeMessage(w,actor),null);step(w);assert.equal(actor.action,'Local patrol');assert.ok(validWorld(w));});
test('first-priority receivers preserve the original graph and consume completed goals',()=>{const {w,recipient,source,actor,zone}=directorScene();recipient.brain[0].type='selector';const oldNodes=recipient.brain.map(n=>n.label);connectDirectorInput(w,recipient,'investigate','first');for(const label of oldNodes.filter(l=>l!=='Choose an action'))assert.ok(recipient.brain.some(n=>n.label===label));step(w);source.x=3;step(w);for(let i=0;i<20;i++)step(w);assert.ok(inZone(w,actor,zone.id));assert.equal(activeMessage(w,actor),null);assert.equal(actor.action,'Local patrol');assert.ok(validWorld(w));});
test('captured stat messages can gate tree conditions and contribute numeric utility scores',()=>{const {w,source,actor,s,recipient,r}=directorScene();r.trigger='stat';r.statId=s.id;r.op='>=';r.threshold=10;r.destination='none';const root=recipient.brain[0],condition=Object.assign(makeNode('condition'),{condition:'message',messageKey:'investigate',messageCheck:'value',op:'>=',threshold:15,weight:0});recipient.brain.push(condition);recipient.edges.push(['root',condition.id]);step(w);const message=activeMessage(w,actor,'investigate');assert.equal(messageField(message,'value'),20);assert.equal(actor.stats[s.id],undefined);assert.equal(nodeUtilityScore(w,actor,{weight:0,messageKey:'investigate',messageScore:'value',messageScale:.1}),2);condition.weight=10;step(w);assert.equal(actor.nodeStatus[condition.id],'success');source.stats[s.id]=5;step(w);assert.equal(w.directors[0].log.length,1);source.stats[s.id]=25;step(w);assert.equal(messageField(activeMessage(w,actor,'investigate'),'value'),25);assert.ok(validWorld(w));});
test('named signals reach directors once and custom interaction rules can emit numeric signals',()=>{const {w,sourceTool,source,actor,s,r}=directorScene();r.trigger='signal';r.signal='custom-event';r.captureStat='';r.destination='none';sendSignal(w,source,'other-event',s.id);step(w);assert.equal(activeMessage(w,actor),null);sourceTool.rules.push(rule({name:'Emit event',trigger:'behavior',target:'self',effect:'signal',signal:'custom-event',signalStat:s.id}));const node=Object.assign(makeNode('action'),{action:'rule',ruleId:sourceTool.rules[0].id});sourceTool.brainEnabled=true;sourceTool.brain.push(node);sourceTool.edges.push(['root',node.id]);step(w);sourceTool.brainEnabled=false;step(w);assert.equal(messageField(activeMessage(w,actor,'investigate'),'value'),20);const count=w.directors[0].log.length;step(w);assert.equal(w.directors[0].log.length,count);assert.ok(validWorld(w));});
test('director can choose an explicit zone linked to the observed subject’s zone',()=>{const {w,source,r,actor,zone}=directorScene(),current=Object.assign(makeZone('Subject area'),{cells:[2*WIDTH+2,2*WIDTH+3],links:[zone.id]});w.zones.push(current);r.destination='linked';step(w);source.x=3;step(w);assert.equal(messageField(activeMessage(w,actor),'zone'),zone.id);assert.ok(validWorld(w));});
test('director validation rejects unknown assignments and preserves older projects without adding active directors',()=>{const {w,d}=directorScene();assert.ok(validWorld(w));d.recipients=['unknown'];assert.equal(validWorld(w),false);d.recipients=[];delete w.directors;delete w.signals;const upgraded=normalizeWorld(w);assert.deepEqual(upgraded.directors,[]);assert.deepEqual(upgraded.signals,[]);assert.ok(validWorld(upgraded));});
test('director UI configures an observer, rule, recipient graph, and generic test input',()=>{const {editor,get}=bootEditor();get('newDirector').click();get('directorName').value='Central observer';get('directorEnabled').checked=true;get('saveDirector').click();const w=editor.world(),d=w.directors.at(-1),bot=w.tools.find(t=>t.kind==='creature');assert.equal(d.name,'Central observer');d.recipients=[bot.id];editor.goGuide(3);get('inspectDirectorDebug').click();get('observedSignal').value='test-input';get('signalObserved').click();assert.equal(w.signals.at(-1).name,'test-input');assert.ok(validWorld(w));});

test('HTTP persistence retains director observations, rules and recipient inboxes',async()=>{const {w,source,actor}=directorScene();w.id='test-'+crypto.randomUUID();step(w);source.x=3;step(w);assert.ok(activeMessage(w,actor));const server=makeServer();await new Promise(r=>server.listen(0,'127.0.0.1',r));const url='http://127.0.0.1:'+server.address().port+'/api/projects/'+w.id;try{const saved=await fetch(url,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(w)});assert.equal(saved.status,200,await saved.text());const loaded=await (await fetch(url)).json();assert.deepEqual(loaded.directors,w.directors);assert.deepEqual(loaded.entities,w.entities);assert.deepEqual(loaded.zones,w.zones);assert.ok(activeMessage(loaded,loaded.entities.find(e=>e.id===actor.id)));assert.ok(validWorld(loaded));}finally{await new Promise(r=>server.close(r));await unlink(new URL('./data/'+w.id+'.json',import.meta.url)).catch(()=>{});}});

test('pursuit hints are approximate, scores are editable, and tutorial controls expose existing settings',()=>{const w=createDemoWorld(),bot=w.entities.find(e=>e.id===w.tutorial.botId);for(let i=0;i<120&&!activeMessage(w,bot,'investigate');i++)step(w);const m=activeMessage(w,bot,'investigate');assert.ok(m);assert.deepEqual(Object.keys(m.fields),['area']);assert.equal(m.fields.value,undefined);assert.equal(m.fields.area.type,'area');assert.ok(messageField(m,'area').length>0);assert.equal(w.directors[0].rules[0].fields[0].zoneId,w.zones.find(z=>z.name==='Inner surroundings').id);const t=w.tools.find(t=>t.id===bot.toolId),receiver=t.brain.find(n=>n.messageKey==='investigate'&&n.type==='sequence');assert.equal(nodeUtilityScore(w,bot,receiver),4);receiver.weight=0;assert.equal(nodeUtilityScore(w,bot,receiver),0);const {editor,get}=bootEditor();assert.equal(editor.running(),false);get('guideSubject').click();assert.ok(get('inspector').innerHTML.includes('Moving subject'));get('inspectBrain').click();assert.ok(get('brainNodes').innerHTML.includes('Emit activity'));get('guideDirector').click();assert.equal(get('directorsView').classList.contains('hidden'),false);editor.goGuide(3);assert.ok(get('brainNodes').innerHTML.includes('Investigate a director hint'));assert.ok(Number.parseInt(get('brainNodes').style.height)>1500);});

test('expanded map has alternate doorways and actual paths detour around editable collision',()=>{const w=createDemoWorld(),bot=w.entities.find(e=>e.id===w.tutorial.botId),west={enabled:true,cells:[16*WIDTH+16]},path=zonePath(w,bot,west);assert.ok(w.entities.length<500);assert.ok(path.length>1);assert.deepEqual(nextZoneStep(w,bot,west),path[1]);const crossings=path.filter(p=>p.x===23);assert.ok(crossings.some(p=>[14,15,28,29].includes(p.y)));const upper=crossings.some(p=>p.y<20),wall=w.tools.find(t=>t.collision);for(const y of upper?[14,15]:[28,29])place(w,wall.id,23,y);const alternative=zonePath(w,bot,west);assert.ok(alternative.length>1);assert.ok(alternative.some(p=>p.x===23&&(upper?p.y>=28:p.y<=15)));const solids=new Set(w.entities.filter(e=>w.tools.find(t=>t.id===e.toolId).collision).map(e=>e.x+','+e.y));for(let i=1;i<alternative.length;i++){assert.ok(!solids.has(alternative[i].x+','+alternative[i].y));assert.equal(Math.abs(alternative[i].x-alternative[i-1].x)+Math.abs(alternative[i].y-alternative[i-1].y),1);}assert.ok(validWorld(w));});
test('debug data is read-only, follows real movement goals, and expires signal markers',()=>{const w=createDemoWorld(),bot=w.entities.find(e=>e.id===w.tutorial.botId);step(w);let before=JSON.stringify(w),data=debugSnapshot(w,bot.id);assert.equal(JSON.stringify(w),before);assert.equal(data.actors.length,1);assert.equal(data.actors[0].goal.kind,'zone');const goal=w.zones.find(z=>z.id===data.actors[0].goal.id);assert.deepEqual(data.actors[0].path,navigationPath(w,bot));assert.ok(data.collisions.length>100);assert.ok(data.actors[0].scores.some(s=>s.score===1));for(let i=0;i<100&&!activeMessage(w,bot,'investigate');i++)step(w);before=JSON.stringify(w);data=debugSnapshot(w,bot.id);assert.equal(JSON.stringify(w),before);assert.equal(data.links.length,1);assert.equal(data.links[0].message,'investigate');assert.equal(data.links[0].value,undefined);assert.ok(data.signals.some(s=>s.name==='activity'));const signal=data.signals.at(-1),captured={x:signal.x,y:signal.y};w.entities.find(e=>e.id===signal.sourceId).x++;assert.deepEqual({x:debugSnapshot(w,bot.id).signals.at(-1).x,y:debugSnapshot(w,bot.id).signals.at(-1).y},captured);w.tick=signal.tick+9;assert.ok(!debugSnapshot(w,bot.id).signals.some(s=>s.id===signal.id));w.directors[0].enabled=false;assert.deepEqual(debugSnapshot(w,bot.id).links,[]);assert.equal(debugSnapshot(w,'',true).actors.length,2);});
test('unreachable goal diagnostics never invent a route and seek paths match movement',()=>{const {w,a,b}=scene(),actor=place(w,a.id,2,2),target=place(w,b.id,5,2),z=Object.assign(makeZone('Blocked'),{cells:[2*WIDTH+5]});w.zones.push(z);assert.deepEqual(targetPath(w,actor,target)[1],nextStep(w,actor,target));for(const [x,y]of [[1,2],[3,2],[2,1],[2,3]])place(w,b.id,x,y);assert.deepEqual(zonePath(w,actor,z),[]);assert.equal(nextZoneStep(w,actor,z),null);const n=Object.assign(makeNode('action'),{action:'zone',zoneId:z.id});a.kind='creature';a.brain.push(n);a.edges.push(['root',n.id]);a.brainEnabled=true;actor.activeNodes=[n.id];actor.nodeStatus={[n.id]:'running'};const data=debugSnapshot(w,actor.id);assert.equal(data.actors[0].goal.reachable,false);assert.deepEqual(data.actors[0].path,[]);});
test('debug controls toggle all layers without altering a project or its timeline',()=>{const {editor,get}=bootEditor(),w=editor.world();get('step').click();const before=JSON.stringify(w);for(const id of ['debugCollision','debugPaths','debugHints','debugSignals','debugLabels','debugAll']){get(id).checked=true;get(id).onchange();}assert.ok(get('debugReadout').innerHTML.includes('Pursuer'));assert.ok(get('debugReadout').innerHTML.includes('Moving subject'));assert.ok(get('debugReadout').innerHTML.includes('Scores now'));get('debugEnabled').checked=false;get('debugEnabled').onchange();assert.equal(get('debugPaths').disabled,true);assert.ok(get('debugReadout').textContent.includes('Overlays off'));get('debugEnabled').checked=true;get('debugEnabled').onchange();assert.equal(get('debugPaths').disabled,false);assert.equal(JSON.stringify(w),before);assert.equal(editor.running(),false);});

test('investigation reaches its accepted point before giving up, even when newer hints arrive',()=>{const {w,source,actor,recipient,r,zone}=directorScene();zone.cells=[];for(let y=2;y<=6;y++)for(let x=12;x<=17;x++)zone.cells.push(y*WIDTH+x);r.ttl=120;connectDirectorInput(w,recipient,'investigate','utility');const action=recipient.brain.find(n=>n.action==='directive');Object.assign(action,{goalMode:'point',finishGoal:true,minTravel:5,routeStyle:'varied',diagonal:true});step(w);source.x=3;step(w);const accepted=actor.acceptedMessage.message.id,point={x:actor.navigation.x,y:actor.navigation.y};assert.ok(Math.hypot(point.x-actor.x,point.y-actor.y)>=3);source.x=4;step(w);assert.equal(actor.acceptedMessage.message.id,accepted);assert.deepEqual({x:actor.navigation.x,y:actor.navigation.y},point);let completed=false;for(let i=0;i<80;i++){step(w);if(!actor.acceptedMessage){assert.deepEqual({x:actor.x,y:actor.y},point);completed=true;break;}assert.notEqual(actor.action,'Local patrol');}assert.ok(completed);assert.ok(w.events.some(e=>e.text.includes('completed message investigate')));assert.ok(validWorld(w));});
test('a user-built choose/move/remember/wait chain varies destinations and resumes after save/load',()=>{const w=createDemoWorld(),bot=w.entities.find(e=>e.id===w.tutorial.botId);w.directors[0].enabled=false;const visits=[];let previous=-1;for(let i=0;i<600;i++){step(w);const last=bot.locationHistory?.visited?.at(-1);if(last&&last.tick!==previous){previous=last.tick;visits.push(last.x+','+last.y);}assert.ok(validWorld(w));}assert.ok(visits.length>=6);assert.ok(new Set(visits).size>=4);for(let i=1;i<visits.length;i++)assert.notEqual(visits[i],visits[i-1]);const saved=normalizeWorld(JSON.parse(JSON.stringify(w)));for(let i=0;i<80;i++){step(w);step(saved);}assert.deepEqual(saved.entities,w.entities);assert.deepEqual(saved.signals.map(({id,...s})=>s),w.signals.map(({id,...s})=>s));});
test('varied routes are stable per goal, can differ between goals, and diagonals cannot cut corners',()=>{const w=createWorld(),t=makeCreatureTool();w.tools.push(t);const e=place(w,t.id,2,2),base={x:14,y:11,zoneId:'debug-zone',key:'test',routeStyle:'varied',diagonal:true,seed:1};const one=navigationPath(w,e,base);assert.deepEqual(navigationPath(w,e,base),one);const routes=new Set();for(let seed=1;seed<=8;seed++)routes.add(JSON.stringify(navigationPath(w,e,{...base,seed})));assert.ok(routes.size>1);const wall=makeTool('Corner','solid');w.tools.push(wall);place(w,wall.id,3,2);place(w,wall.id,2,3);const route=navigationPath(w,e,{...base,x:3,y:3});assert.ok(route.length>2);for(let i=1;i<route.length;i++){const a=route[i-1],b=route[i];if(a.x!==b.x&&a.y!==b.y){assert.ok(!w.entities.some(v=>v.toolId===wall.id&&((v.x===a.x&&v.y===b.y)||(v.x===b.x&&v.y===a.y))));}}});
test('utility commitment resists weaker reevaluation but allows stronger interruption and director disable',()=>{const {w,source,actor,recipient,d,r}=directorScene();connectDirectorInput(w,recipient,'investigate','utility');Object.assign(recipient.brain[0],{commitRunning:true,commitTicks:100,interruptMargin:1});const follow=recipient.brain.find(n=>n.action==='directive');Object.assign(follow,{goalMode:'point',finishGoal:true});step(w);source.x=3;step(w);assert.ok(actor.acceptedMessage);d.enabled=false;step(w);assert.equal(activeMessage(w,actor),null);assert.equal(actor.action,'Local patrol');assert.ok(validWorld(w));});
test('node editor exposes independent selection, memory, movement and sequence controls',()=>{const {editor,get}=bootEditor(),w=editor.world(),t=w.tools.find(t=>t.id===w.tutorial.toolId),choose=t.brain.find(n=>n.action==='chooseTarget'&&n.slot==='destination');editor.editBrainNode(t.id,choose.id);assert.equal(get('nodeAction').value,'chooseTarget');assert.equal(get('nodeSelectionSource').value,'zones');get('nodeZoneRelation').value='outside';get('saveBrainNode').click();assert.equal(t.brain.find(n=>n.id===choose.id).zoneRelation,'outside');assert.equal(t.brain.find(n=>n.id===choose.id).selectionZones.length,1);const sequence=t.brain.find(n=>n.type==='sequence'&&n.weight===1);editor.editBrainNode(t.id,sequence.id);assert.equal(get('nodeSequenceMode').value,'memory');get('nodeResetInterrupted').checked=false;get('saveBrainNode').click();assert.equal(t.brain.find(n=>n.id===sequence.id).resetOnInterrupt,false);editor.editBrainNode(t.id,'root');assert.equal(get('nodeCommitRunning').checked,true);assert.ok(!get('nodeAction').innerHTML.includes('value="patrol"'));get('nodeInterruptMargin').value='2';get('saveBrainNode').click();assert.equal(t.brain[0].interruptMargin,2);assert.ok(validWorld(w));});

test('demo action chains reach stored input points across varied random choices',()=>{for(let seed=1;seed<=6;seed++){const w=createDemoWorld(),bot=w.entities.find(e=>e.id===w.tutorial.botId),t=w.tools.find(t=>t.id===bot.toolId),move=t.brain.find(n=>n.action==='moveTarget'&&n.slot==='hint');bot.randomState=seed;let tracked=null,completed=0;for(let i=0;i<400;i++){step(w);const status=bot.nodeStatus[move.id],target=bot.targets?.hint;if(status==='running'){if(!tracked)tracked={id:target.message.id,point:{x:target.x,y:target.y}};assert.equal(target.message.id,tracked.id);assert.deepEqual({x:target.x,y:target.y},tracked.point);}if(tracked&&status==='success'){assert.deepEqual({x:bot.x,y:bot.y},tracked.point);completed++;tracked=null;}assert.ok(validWorld(w));}assert.ok(completed>=3,'stored input points must actually be reached');assert.ok(w.tools.every(t=>t.brain.every(n=>!['patrol','directive','seek'].includes(n.action))));}});
test('commitment keeps a weaker ongoing goal but yields to an explicitly stronger branch',()=>{const {w,source,actor,recipient}=directorScene();connectDirectorInput(w,recipient,'investigate','utility');Object.assign(recipient.brain[0],{commitRunning:true,commitTicks:100,interruptMargin:1});const receiver=recipient.brain.find(n=>n.type==='sequence'&&n.messageKey==='investigate');step(w);source.x=3;step(w);const m=activeMessage(w,actor);m.fields.priority.value=0;step(w);assert.equal(actor.nodeStatus[receiver.id],'running');const urgent=Object.assign(makeNode('action'),{label:'Explicit stronger interruption',weight:10});recipient.brain.push(urgent);recipient.edges.push(['root',urgent.id]);step(w);assert.equal(actor.action,'Explicit stronger interruption');assert.ok(validWorld(w));});
test('point movement respects immobile tools and accepted input expires cleanly',()=>{const {w,source,actor,recipient,r}=directorScene();connectDirectorInput(w,recipient,'investigate','utility');Object.assign(recipient.brain.find(n=>n.action==='directive'),{goalMode:'point',finishGoal:true});r.ttl=2;step(w);source.x=3;step(w);assert.ok(actor.acceptedMessage);step(w);step(w);assert.equal(actor.acceptedMessage,undefined);assert.equal(actor.action,'Local patrol');recipient.mobile=false;const before={x:actor.x,y:actor.y};const result=executeAction(w,actor,{...makeNode('action'),action:'zone',goalMode:'point',zoneId:w.zones[0].id});assert.equal(result,'failure');assert.deepEqual({x:actor.x,y:actor.y},before);});

test('HTTP save/load retains stored input points and independent sequence progress',async()=>{const w=createDemoWorld();w.id='test-'+crypto.randomUUID();const bot=w.entities.find(e=>e.id===w.tutorial.botId),move=w.tools.find(t=>t.id===bot.toolId).brain.find(n=>n.action==='moveTarget'&&n.slot==='hint');for(let i=0;i<150&&bot.nodeStatus?.[move.id]!=='running';i++)step(w);assert.ok(bot.targets.hint.message);const server=makeServer();await new Promise(r=>server.listen(0,'127.0.0.1',r));const url='http://127.0.0.1:'+server.address().port+'/api/projects/'+w.id;try{const saved=await fetch(url,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(w)});assert.equal(saved.status,200,await saved.text());const loaded=await (await fetch(url)).json(),copy=loaded.entities.find(e=>e.id===bot.id);assert.deepEqual(copy.targets,bot.targets);assert.deepEqual(copy.sequenceMemory,bot.sequenceMemory);assert.deepEqual(copy.locationHistory,bot.locationHistory);assert.deepEqual(copy.utilityMemory,bot.utilityMemory);for(let i=0;i<10;i++){step(w);step(loaded);}assert.deepEqual(loaded.entities.map(e=>[e.x,e.y,e.stats,e.randomState,e.navigation]),w.entities.map(e=>[e.x,e.y,e.stats,e.randomState,e.navigation]));assert.ok(validWorld(loaded));}finally{await new Promise(r=>server.close(r));await unlink(new URL('./data/'+w.id+'.json',import.meta.url)).catch(()=>{});}});

test('the complete example can be reconstructed through editor controls from New canvas',()=>{const recipe=createDemoWorld(),{world,ids}=rebuildThroughEditor(recipe);assertEquivalentRecipe(recipe,world,ids);assert.ok(validWorld(world));assert.notEqual(world.id,recipe.id);assert.equal(world.tutorial,undefined);const bot=world.entities.find(e=>world.tools.find(t=>t.id===e.toolId).name==='Pursuer');const imported=normalizeWorld(JSON.parse(JSON.stringify(world)));for(let i=0;i<400;i++){step(world);step(imported);}assert.ok(bot.locationHistory.inspected.length>=3);assert.ok(bot.locationHistory.visited.length>=1);assert.deepEqual(imported.entities.map(e=>[e.x,e.y,e.stats,e.randomState]),world.entities.map(e=>[e.x,e.y,e.stats,e.randomState]));assert.ok(validWorld(imported));});
test('choose, move, wait and history actions are independent and can be reordered',()=>{const {w,a}=scene(),z=Object.assign(makeZone('Arbitrary area'),{cells:[2*WIDTH+10,3*WIDTH+10]});w.zones.push(z);a.kind='creature';const e=place(w,a.id,2,2),choose={...makeNode('action'),action:'chooseTarget',slot:'customGoal',selectionSource:'zones',selectionZones:[z.id],avoidRecent:0},before={x:e.x,y:e.y};assert.equal(executeAction(w,e,choose),'success');assert.deepEqual({x:e.x,y:e.y},before);const point=structuredClone(e.targets.customGoal);const wait={...makeNode('action'),action:'wait',waitMin:3,waitMax:3};assert.equal(executeAction(w,e,wait),'running');assert.deepEqual({x:e.x,y:e.y},before);for(let i=1;i<=3;i++){w.tick++;assert.equal(executeAction(w,e,wait),i===3?'success':'running');}assert.equal(e.locationHistory,undefined);const move={...makeNode('action'),action:'moveTarget',slot:'customGoal',routeStyle:'varied',diagonal:true};for(let i=0;i<30;i++)if(executeAction(w,e,move)==='success')break;assert.deepEqual({x:e.x,y:e.y},{x:point.x,y:point.y});assert.equal(executeAction(w,e,{...makeNode('action'),action:'rememberTarget',slot:'customGoal',historyKey:'myLocations',historyLimit:4}),'success');assert.equal(e.locationHistory.myLocations.length,1);assert.equal(executeAction(w,e,{...makeNode('action'),action:'clearTarget',slot:'customGoal'}),'success');assert.equal(e.targets.customGoal,undefined);assert.equal(e.locationHistory.myLocations.length,1);assert.ok(validWorld(w));});
test('point selection can target inside or outside areas, current areas, or a radius around a stored point',()=>{const {w,a}=scene(),inside=Object.assign(makeZone('Inside'),{cells:[2*WIDTH+2,2*WIDTH+3]}),outside=Object.assign(makeZone('Outside'),{cells:[10*WIDTH+10,10*WIDTH+11]});w.zones.push(inside,outside);const e=place(w,a.id,2,2),pick={...makeNode('action'),action:'chooseTarget',slot:'chosen',selectionSource:'zones',selectionZones:[inside.id,outside.id],zoneRelation:'outside',avoidRecent:0};assert.equal(executeAction(w,e,pick),'success');assert.equal(e.targets.chosen.zoneId,outside.id);pick.zoneRelation='inside';assert.equal(executeAction(w,e,pick),'success');assert.equal(e.targets.chosen.zoneId,inside.id);pick.selectionSource='current';pick.zoneRelation='any';assert.equal(executeAction(w,e,pick),'success');assert.equal(e.targets.chosen.zoneId,inside.id);const anchor={...e.targets.chosen,x:15,y:15};e.targets.anchor=anchor;Object.assign(pick,{selectionSource:'radius',originSlot:'anchor',radius:2});assert.equal(executeAction(w,e,pick),'success');assert.ok(Math.hypot(e.targets.chosen.x-15,e.targets.chosen.y-15)<=2);const retained=structuredClone(e.targets.chosen);pick.choosePolicy='keep';assert.equal(executeAction(w,e,pick),'success');assert.deepEqual(e.targets.chosen,retained);assert.ok(validWorld(w));});
test('history filters and target conditions have no implicit patrol behavior',()=>{const {w,a}=scene(),z=Object.assign(makeZone(),{cells:[4*WIDTH+4,4*WIDTH+5]});w.zones.push(z);const e=place(w,a.id,1,1),pick={...makeNode('action'),action:'chooseTarget',slot:'pointA',selectionSource:'zones',selectionZones:[z.id],avoidRecent:1,historyKey:'anything',historyFallback:false};e.locationHistory={anything:[{x:4,y:4,zoneId:z.id,tick:0}]};assert.equal(executeAction(w,e,pick),'failure');assert.equal(e.targets.pointA,undefined);pick.historyFallback=true;assert.equal(executeAction(w,e,pick),'success');const root=makeNode('sequence','root'),condition=Object.assign(makeNode('condition'),{condition:'target',slot:'pointA',targetCheck:'present'});a.brain=[root,condition];a.edges=[['root',condition.id]];a.brainEnabled=true;step(w);assert.equal(e.nodeStatus[condition.id],'success');condition.targetCheck='reached';step(w);assert.equal(e.nodeStatus[condition.id],'failure');assert.deepEqual({x:e.x,y:e.y},{x:1,y:1});assert.ok(validWorld(w));});

test('debug distinguishes the captured input being handled from a newer available input',()=>{const w=createDemoWorld(),bot=w.entities.find(e=>e.id===w.tutorial.botId),source=w.entities.find(e=>e.id===w.tutorial.subjectId);w.tools.find(t=>t.id===source.toolId).brainEnabled=false;sendSignal(w,source,'activity',w.tutorial.noiseId);step(w);const captured=bot.targets.hint.message.id,point={x:bot.targets.hint.x,y:bot.targets.hint.y};sendSignal(w,source,'activity',w.tutorial.noiseId);step(w);assert.equal(bot.targets.hint.message.id,captured);assert.deepEqual({x:bot.targets.hint.x,y:bot.targets.hint.y},point);const before=JSON.stringify(w),data=debugSnapshot(w,bot.id);assert.equal(JSON.stringify(w),before);assert.equal(data.links.filter(l=>l.handling).length,1);assert.equal(data.links.filter(l=>!l.handling).length,1);assert.deepEqual(data.actors[0].goal.point,point);assert.ok(validWorld(w));});

test('board and tree stay visible together and show the selected instance results each tick',()=>{const {editor,get,query,tick}=bootEditor(),w=editor.world(),bot=w.entities.find(e=>e.id===w.tutorial.botId);assert.equal(get('boardView').classList.contains('hidden'),false);assert.equal(get('behaviorView').classList.contains('hidden'),false);assert.equal(get('editorLayout').classList.contains('split-active'),true);get('play').click();tick();assert.equal(w.tick,1);assert.ok(get('brainLiveStatus').textContent.includes('Tick 1'));for(const n of w.tools.find(t=>t.id===bot.toolId).brain){const el=get('brainNodes').querySelector('[data-node="'+n.id+'"]'),badge=get('brainNodes').querySelector('[data-result="'+n.id+'"]'),state=bot.nodeStatus[n.id]??'';assert.equal(el.dataset.state,state);assert.equal(badge.textContent,state.toUpperCase());}assert.ok(get('brainGraph').scrollTop>0);get('brainFollow').checked=false;get('brainFollow').onchange();get('brainGraph').scrollTo({left:10,top:20});tick();assert.equal(w.tick,2);assert.equal(get('brainGraph').scrollLeft,10);assert.equal(get('brainGraph').scrollTop,20);get('play').click();const before=JSON.stringify(w);get('toggleSplit').click();assert.equal(get('boardView').classList.contains('hidden'),false);assert.equal(get('behaviorView').classList.contains('hidden'),true);query('[data-view="behavior"]')[0].click();assert.equal(get('boardView').classList.contains('hidden'),true);assert.equal(get('behaviorView').classList.contains('hidden'),false);get('toggleSplit').click();assert.equal(get('boardView').classList.contains('hidden'),false);assert.equal(get('behaviorView').classList.contains('hidden'),false);get('toggleInspector').click();assert.equal(get('editorLayout').classList.contains('inspector-open'),true);query('[data-view="stats"]')[0].click();assert.equal(get('simulationWorkspace').classList.contains('hidden'),true);query('[data-view="board"]')[0].click();assert.equal(get('simulationWorkspace').classList.contains('hidden'),false);assert.equal(JSON.stringify(w),before);});
test('the live tree can watch a second painted instance instead of silently showing the first',()=>{const {editor,get}=bootEditor(),w=editor.world(),source=w.tools.find(t=>t.id===w.tutorial.subjectToolId);get('toolList').querySelector('[data-tool="'+source.id+'"]').click();const transform=editor.transform(),event={clientX:transform.x+5.5*transform.size,clientY:transform.y+5.5*transform.size,pointerId:1};get('board').onpointerdown(event);get('board').onpointerup();const placed=w.entities.find(e=>e.toolId===source.id&&e.x===5&&e.y===5);assert.ok(placed);assert.ok(get('brainInstance').innerHTML.includes(placed.id));get('brainInstance').value=placed.id;get('brainInstance').onchange();get('step').click();assert.ok(get('brainLiveStatus').textContent.includes('('+placed.x+', '+placed.y+')'));for(const n of source.brain)assert.equal(get('brainNodes').querySelector('[data-result="'+n.id+'"]').textContent,(placed.nodeStatus[n.id]??'').toUpperCase());assert.equal(get('boardView').classList.contains('hidden'),false);assert.equal(get('behaviorView').classList.contains('hidden'),false);});

function attachedZone(w,anchor,extra={}){const z=Object.assign(makeZone('Relative area'),{placement:'attached',anchorKind:'entity',anchorEntity:anchor.id,anchorTool:'',anchorTag:'',shape:'circle',innerRadius:2,outerRadius:4,offsetX:0,offsetY:0},extra);w.zones.push(z);return z;}
test('attached rings follow ordinary objects, preserve painted cells, and lose absent anchors',()=>{const {w,a}=scene(),anchor=place(w,a.id,10,10),z=attachedZone(w,anchor);z.cells=[0];assert.equal(inZone(w,anchor,z.id),false);assert.equal(inZone(w,{x:13,y:10},z.id),true);anchor.x=20;assert.equal(inZone(w,{x:13,y:10},z.id),false);assert.equal(inZone(w,{x:23,y:10},z.id),true);z.placement='painted';assert.deepEqual(zoneCells(w,z),[0]);z.placement='attached';anchor.removed=true;assert.deepEqual(zoneCells(w,z),[]);assert.ok(validWorld(w));});
test('tool and tag anchors combine square areas, clamp board edges, and track membership changes',()=>{const {w,a}=scene(),one=place(w,a.id,0,0),two=place(w,a.id,15,15),tag=defineTag(w,'anchor','Area origin');const z=attachedZone(w,one,{anchorKind:'tool',anchorTool:a.id,shape:'square',innerRadius:0,outerRadius:1});assert.equal(zoneCells(w,z).length,13);assert.equal(inZone(w,{x:16,y:16},z.id),true);z.anchorKind='tag';z.anchorTag=tag.id;assert.deepEqual(zoneCells(w,z),[]);two.tags.push(tag.id);assert.equal(zoneCells(w,z).length,9);z.offsetX=2;assert.equal(inZone(w,{x:18,y:15},z.id),true);assert.ok(validWorld(w));});
test('attached areas drive exact-stat effects, utility scores, point choice and director inputs',()=>{const {w,a,s}=scene(),anchor=place(w,a.id,10,10),actor=place(w,a.id,13,10),z=attachedZone(w,anchor,{effect:'stat',stat:s.id,amount:3,creaturesOnly:false});applyZones(w);assert.equal(actor.stats[s.id],23);assert.equal(anchor.stats[s.id],20);const score=nodeUtilityScore(w,actor,{weight:1,scoreZone:z.id,zoneMultiplier:3});assert.equal(score,3);assert.equal(executeAction(w,actor,{action:'chooseTarget',slot:'destination',selectionSource:'zones',selectionZones:[z.id]}),'success');const point={...actor.targets.destination};assert.ok(inZone(w,point,z.id));anchor.x=30;assert.deepEqual(actor.targets.destination,point);assert.equal(executeAction(w,actor,{action:'chooseTarget',slot:'destination',selectionSource:'zones',selectionZones:[z.id]}),'success');assert.ok(inZone(w,actor.targets.destination,z.id));const d=makeDirector('Observer');d.enabled=true;d.watchEntity=anchor.id;d.recipients=[a.id];a.kind='creature';d.rules.push(Object.assign(makeDirectorRule(),{trigger:'always',destination:'fixed',goalZone:z.id,message:'area',fields:[{name:'zone',type:'zone',source:'constant',value:z.id}]}));w.directors.push(d);step(w);assert.equal(messageField(activeMessage(w,actor,'area'),'zone'),z.id);assert.equal(executeAction(w,actor,{action:'chooseTarget',slot:'hint',selectionSource:'message',messageKey:'area'}),'success');assert.ok(inZone(w,actor.targets.hint,z.id));assert.ok(debugSnapshot(w));assert.ok(validWorld(normalizeWorld(JSON.parse(JSON.stringify(w)))));});
test('relative zone editor exposes generic settings and can switch back without losing paint',()=>{const {editor,get}=bootEditor(),w=editor.world(),z=w.zones[0],paint=[...z.cells],anchor=w.entities.find(e=>e.id===w.tutorial.subjectId);editor.editZone(z.id);get('zonePlacement').value='attached';get('zonePlacement').onchange();get('zoneAnchorEntity').value=anchor.id;get('zoneInnerRadius').value='3';get('zoneOuterRadius').value='7';get('saveZone').click();let saved=w.zones.find(v=>v.id===z.id);assert.equal(saved.placement,'attached');assert.equal(saved.anchorEntity,anchor.id);assert.ok(validWorld(w));assert.equal(inZone(w,anchor,z.id),false);editor.editZone(z.id);get('zonePlacement').value='painted';get('saveZone').click();saved=w.zones.find(v=>v.id===z.id);assert.deepEqual(zoneCells(w,saved),paint);assert.ok(validWorld(w));});
test('invalid attached geometry is rejected and missing removed instance anchors remain loadable',()=>{const {w,a}=scene(),anchor=place(w,a.id,8,8),z=attachedZone(w,anchor);z.innerRadius=9;assert.equal(validWorld(w),false);z.innerRadius=2;z.outerRadius=2.5;assert.equal(validWorld(w),false);z.outerRadius=4;w.entities=[];assert.ok(validWorld(w));assert.deepEqual(zoneCells(w,z),[]);z.anchorKind='tool';z.anchorTool='unknown';assert.equal(validWorld(w),false);});

test('demo uses a general movement boundary and attached roaming and investigation areas',()=>{const w=createDemoWorld(),occupied=new Set();assert.deepEqual(w.zones.map(z=>z.name),['General area','Outer surroundings','Inner surroundings','Subject roaming range']);for(const z of w.zones.filter(z=>z.placement!=='attached'))for(const cell of zoneCells(w,z)){assert.ok(!occupied.has(cell));occupied.add(cell);}const moving=w.zones.find(z=>z.name==='Inner surroundings'),actor=w.entities.find(e=>e.id===w.tutorial.botId),source=w.entities.find(e=>e.id===w.tutorial.subjectId);w.tools.find(t=>t.id===source.toolId).brainEnabled=false;sendSignal(w,source,'activity');step(w);const m=activeMessage(w,actor);assert.equal(m.fields.area.type,'area');const copy=[...messageField(m,'area')];assert.deepEqual(copy,zoneCells(w,moving));source.x+=12;assert.notDeepEqual(zoneCells(w,moving),copy);assert.deepEqual(messageField(m,'area'),copy);assert.equal(Object.hasOwn(m,'x'),false);assert.equal(executeAction(w,actor,{action:'chooseTarget',slot:'test',selectionSource:'message',messageKey:'investigate',messageTargetField:'area'}),'success');assert.ok(copy.includes(actor.targets.test.y*WIDTH+actor.targets.test.x));assert.ok(validWorld(normalizeWorld(JSON.parse(JSON.stringify(w)))));});

function movementScene(){const w=createWorld(),t=makeCreatureTool('Walker');w.tools.push(t);const actor=place(w,t.id,2,2),zone=(name,points)=>{const z=Object.assign(makeZone(name),{cells:points.map(([x,y])=>y*WIDTH+x)});w.zones.push(z);return z;};return {w,t,actor,zone};}
test('optional movement limits combine zones, constrain full routes, and reject disconnected destinations',()=>{const {w,t,actor,zone}=movementScene(),a=zone('First',[[2,2],[2,3],[3,3]]),b=zone('Second',[[4,3],[4,2]]),goal=zone('Goal',[[4,2]]);t.allowedMovementZones=[a.id,b.id];for(const options of [{},{diagonal:true},{diagonal:true,routeStyle:'varied',seed:9}]){const path=zonePath(w,actor,goal,options);assert.equal(path.length,5);assert.ok(path.every(p=>[...a.cells,...b.cells].includes(p.y*WIDTH+p.x)));}const move={action:'zone',zoneId:goal.id,diagonal:true,routeStyle:'varied'};for(let i=0;i<5;i++)executeAction(w,actor,move);assert.deepEqual([actor.x,actor.y],[4,2]);actor.x=2;actor.y=2;t.allowedMovementZones=[a.id,goal.id];assert.deepEqual(zonePath(w,actor,goal),[]);assert.equal(executeAction(w,actor,{action:'chooseTarget',selectionSource:'zones',selectionZones:[goal.id],slot:'destination'}),'failure');t.allowedMovementZones=[];assert.ok(zonePath(w,actor,goal).some(p=>p.x===3&&p.y===2));assert.ok(validWorld(w));});
test('wander honors zone boundaries and becomes unrestricted when selections are cleared',()=>{const {w,t,actor,zone}=movementScene(),a=zone('Small',[[2,2],[3,2],[2,3],[3,3]]);t.allowedMovementZones=[a.id];for(let i=0;i<100;i++){w.tick++;executeAction(w,actor,{action:'wander',diagonal:true});assert.ok(a.cells.includes(actor.y*WIDTH+actor.x));}t.allowedMovementZones=[];let outside=false;for(let i=0;i<100;i++){w.tick++;executeAction(w,actor,{action:'wander',diagonal:true});outside ||= !a.cells.includes(actor.y*WIDTH+actor.x);}assert.ok(outside);});
test('edited or disabled allowed zones stop existing destinations without moving outside',()=>{const {w,t,actor,zone}=movementScene(),a=zone('Allowed',[[2,2],[3,2],[4,2]]),goal=zone('Goal',[[4,2]]);t.allowedMovementZones=[a.id];assert.equal(executeAction(w,actor,{action:'chooseTarget',selectionSource:'zones',selectionZones:[goal.id],slot:'destination'}),'success');a.cells=[2*WIDTH+2];assert.equal(executeAction(w,actor,{action:'moveTarget',slot:'destination'}),'failure');assert.deepEqual([actor.x,actor.y],[2,2]);a.enabled=false;assert.equal(executeAction(w,actor,{action:'wander'}),'failure');assert.deepEqual([actor.x,actor.y],[2,2]);assert.ok(validWorld(w));});
test('seek and automatic spawning respect assigned movement zones',()=>{const {w,t,actor,zone}=movementScene(),a=zone('Allowed',[[2,2],[2,3]]),target=makeTool('Target');w.tools.push(target);place(w,target.id,5,2);t.allowedMovementZones=[a.id];assert.equal(executeAction(w,actor,{action:'seek',targetTool:target.id}),'failure');Object.assign(t.spawn,{enabled:true,interval:1,limit:2,x:50,y:30});step(w);assert.equal(w.entities.filter(e=>e.toolId===t.id).length,2);assert.ok(w.entities.filter(e=>e.toolId===t.id).every(e=>a.cells.includes(e.y*WIDTH+e.x)));});
test('movement zone assignments validate, persist, and old projects remain unrestricted',()=>{const {w,t,zone}=movementScene(),a=zone('Allowed',[[2,2]]);t.allowedMovementZones=['unknown'];assert.equal(validWorld(w),false);t.allowedMovementZones=[a.id,a.id];assert.equal(validWorld(w),false);t.allowedMovementZones=[a.id];assert.deepEqual(normalizeWorld(JSON.parse(JSON.stringify(w))).tools[0].allowedMovementZones,[a.id]);delete t.allowedMovementZones;assert.ok(validWorld(normalizeWorld(w)));});
test('creature editor saves multiple optional movement zones and protects referenced zone deletion',()=>{const {editor,get}=bootEditor(),w=editor.world(),t=w.tools.find(t=>t.id===w.tutorial.toolId);get('creatureCards').querySelector('[data-creature-config="'+t.id+'"]').click();const rows=get('dialogBody').querySelectorAll('[data-movement-zone]');assert.equal(rows.length,w.zones.length);rows[0].checked=true;rows[2].checked=true;get('saveTool').click();assert.deepEqual(Array.from(w.tools.find(v=>v.id===t.id).allowedMovementZones),[w.zones[0].id,w.zones[2].id]);editor.editZone(w.zones[2].id);get('deleteZone').click();assert.ok(get('formError').textContent);assert.equal(w.zones.length,4);get('cancelZone').click();get('creatureCards').querySelector('[data-creature-config="'+t.id+'"]').click();for(const el of get('dialogBody').querySelectorAll('[data-movement-zone]'))el.checked=false;get('saveTool').click();assert.equal(w.tools.find(v=>v.id===t.id).allowedMovementZones.length,0);assert.ok(validWorld(w));});
test('demo roaming needs no message and signaling selects the separate inner snapshot',()=>{const w=createDemoWorld(),actor=w.entities.find(e=>e.id===w.tutorial.botId),source=w.entities.find(e=>e.id===w.tutorial.subjectId),outer=w.zones.find(z=>z.name==='Outer surroundings'),inner=w.zones.find(z=>z.name==='Inner surroundings'),subject=w.tools.find(t=>t.id===source.toolId);assert.ok(subject.brain.some(n=>n.action==='wait'&&n.waitMin===8&&n.waitMax===24));assert.ok(w.tools.filter(t=>t.kind==='creature').every(t=>t.allowedMovementZones.includes(w.tutorial.primaryZone)));subject.brainEnabled=false;step(w);assert.equal(activeMessage(w,actor),null);assert.equal(actor.targets.destination.zoneId,outer.id);assert.ok(zoneCells(w,outer).includes(actor.targets.destination.y*WIDTH+actor.targets.destination.x));sendSignal(w,source,'activity');step(w);assert.ok(actor.targets.hint?.message);assert.deepEqual(messageField(actor.targets.hint.message,'area'),zoneCells(w,inner));assert.ok(zoneCells(w,inner).includes(actor.targets.hint.y*WIDTH+actor.targets.hint.x));w.directors[0].enabled=false;let resumed=false;for(let i=0;i<100;i++){step(w);if(!actor.tags.includes(w.tutorial.searchTag)&&actor.targets.destination?.zoneId===outer.id)resumed=true;}assert.equal(activeMessage(w,actor),null);assert.ok(resumed);assert.ok(validWorld(w));});

test('room-free demo picks farther random subject destinations and keeps both creatures inside General area',()=>{const w=createDemoWorld(),subject=w.entities.find(e=>e.id===w.tutorial.subjectId),hunter=w.entities.find(e=>e.id===w.tutorial.botId),general=w.zones.find(z=>z.name==='General area'),range=w.zones.find(z=>z.name==='Subject roaming range'),outer=w.zones.find(z=>z.name==='Outer surroundings'),allowed=new Set(general.cells),destinations=new Set(),signalTicks=[];assert.ok(range.outerRadius>outer.outerRadius);assert.ok(!w.zones.some(z=>/room/i.test(z.name)));assert.ok(!w.tagDefs.some(t=>/Heading east/i.test(t.name)));assert.equal(w.tools.find(t=>t.id===subject.toolId).brain[0].type,'sequence');let selected=-1,lastSignal='';for(let i=0;i<600;i++){const before={x:subject.x,y:subject.y};step(w);assert.ok(allowed.has(subject.y*WIDTH+subject.x));assert.ok(allowed.has(hunter.y*WIDTH+hunter.x));const target=subject.targets?.route;if(target&&target.selectedAt!==selected){selected=target.selectedAt;const distance=Math.hypot(target.x-before.x,target.y-before.y);assert.ok(distance>=range.innerRadius&&distance<=range.outerRadius);destinations.add(target.x+','+target.y);}const signal=w.signals.at(-1);if(signal&&signal.id!==lastSignal){lastSignal=signal.id;signalTicks.push(signal.tick);}}assert.ok(destinations.size>=5);assert.ok(signalTicks.length>=5);assert.ok(new Set(signalTicks.slice(1).map((tick,i)=>tick-signalTicks[i])).size>1);assert.ok(validWorld(w));});
